+fn rejection_result(call: &RejectedCall, reason: &Reason, limit: usize) -> String {
+    let detailed = match reason {
+        Reason::ArgumentSize { len, max } => format!(
+            "{} call {} rejected: arguments are {len} bytes, over the {max}-byte limit. {}",
+            call.tool, call.id,
+            "Create the file with a short first version, then extend it with edits.",
+        ),
+        other => format!("{} call {} rejected: {other}", call.tool, call.id),
+    };
+    if detailed.len() <= limit {
+        return detailed;
+    }
+    // Too long for the configured limit: keep what pairs the result with its call.
+    format!(
+        "Tool call {} to {} was rejected ({}). Fix the call and try again.",
+        call.id, call.tool, reason.code(),
+    )
+}

